WFJ.Data.add("gossip", {
  ["d403eee077aecfb1"] = { "Quale faccenda ti porta davanti alla Corte di ⟦Lakeshire=Borgolago⟧ e all'onorevole magistrato Solomon?", "." },
  ["d40fcf6a0879b912"] = { "Ben fatto! Senza il tuo aiuto non ce l'avrei mai fatta a respingere quell'ondata di trogg.", "." },
  ["d41020c584b37c15"] = { "Il mio mestiere sono le merci e i beni mistici, <straniero/straniera>.", "." },
  ["d413930889d5fe1d"] = { "Certo, certo. Parla con Deze Snowbane alla Hall of the Brave, nella ⟦Valley of Honor=Valle dell'Onore⟧ di questa città, {class}.", "." },
  ["d418b788dddee012"] = { "Voglio attivare il JcJ.", "." },
  ["d41e98e95e4a9263"] = { "Narain, se hai abbastanza materiali, mi servirebbe un'altra boa d'arcanite.", "." },
  ["d41edd3d413c5fac"] = { "Puoi parlarmi quando vuoi, {name}. Hai servito bene Magatha. Di sicuro ti chiamerà ancora in futuro.", "." },
  ["d41f70018d367d06"] = { "Difenditi!", "." },
  ["d421d8c49ff5c87b"] = { "In gioventù, quando vivevo tra gli elfi della notte di ⟦Darkshore=Rivafosca⟧, incrociai la strada di un gruppo di individui poco raccomandabili noti come il ⟦Twilight's Hammer=Martello del Crepuscolo⟧. Alcuni di loro mi fecero amicizia e, con mia vergogna, finii per rinnegare la mia fede in Elune e abbracciare il veleno del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.\n\nSolo quando Elune mi mandò una visione mi risvegliai dal torpore che mi aveva avvolto come seguace degli Dei Antichi.\n\nCome atto di pentimento, iniziai a lavorare alla mia preghiera a Elune.", "." },
  ["d42857c410e36778"] = { "Se sei qui a implorare il privilegio di lavorare per me, la tua compagnia è più che gradita. Altrimenti, difficilmente mi sarai di qualche utilità.", "." },
  ["d42c97a63f1af719"] = { "Predoni a nord! Fuoco!", "." },
  ["d42f05325f277388"] = { "Allora ascolta bene, {class}.\n\nRiesci a sentire il potere che si irradia da me? Il tuo morale non si gonfia? Sì, per l'altra parte è lo stesso. Scompaginare le loro difese e sfoltire le loro truppe non sarà un compito facile, ma va fatto! La vittoria sarà nostra!", "." },
  ["d435dc8bd16d347c"] = { "Dimmi di più sulla forgiatura di armature.", "." },
  ["d43b49dec48bd34a"] = { "Seguimi.", "." },
  ["d43ecd8af0044646"] = { "%s rende un ultimo servigio a Ragnaros...", "." },
  ["d442c682c2a0f5d1"] = { "No! No, no, no! Non può essere. Preferirei essere morta che Reietta!\n\n<La {class} spaventata solleva l'arma, pronta ad attaccare!>", "." },
  ["d4496bbc249d0ca1"] = { "Ciao {name}!\n\nDevo lavorare ai miei congegni, ma prima o poi... mi servirà qualcuno che mi procuri delle uova di drago!", "." },
  ["d44a3e491f9bfa5b"] = { "Mi gira... la testa. Fa così caldo... qui... dentro...", "." },
  ["d4561e9f5c65e5c5"] = { "Horgus è stato ucciso! Coraggio, difensori del ⟦Darrowshire=Borgo di Darrow⟧!", "." },
  ["d456d58340cd60b8"] = { "Te lo porto subito, tesoro...", "." },
  ["d4574faf81d0aa64"] = { "Hai sfidato i Sette, e ora morirai!", "." },
  ["d46a9242be112b2d"] = { "Chi osa risvegliare Archaedas? Chi osa sfidare l'ira dei Creatori?", "." },
  ["d47095d88a21395b"] = { "%s respira in modo irregolare.", "." },
  ["d4722d7b1d5fa25b"] = { "Sei qui in cerca del sapere di Hgarth?", "." },
  ["d47db44650595a3d"] = { "Evoca la ⟦Torch of Retribution=Torcia del Castigo⟧, Kalaran.", "." },
  ["d4840318b445995e"] = { "Pozioni e oli: sono queste le cose che Yelmak ti insegnerà, se ti riterrà all'altezza. Cerca la sua bottega in mezzo a The Drag.", "." },
  ["d48da2343f725705"] = { "⟦Warsong Gulch=Forra dei Cantaguerra⟧, dici? Allora vorrai parlare con la bella Lylandris, laggiù nella Hall of Arms.", "." },
  ["d48e979a34d289dc"] = { "%s non può più muoversi.", "." },
  ["d494ba6cc9fa71ea"] = { "Un sorriso da un orecchio all'altro...", "." },
  ["d49a8d45089d74c1"] = { "Dunque desideri saperne di più sulle nostre armi elfiche? Che la tua prima lezione abbia inizio.", "." },
  ["d49d5e041c0e2bd4"] = { "I venti sussurrano i racconti delle tue battaglie contro i Gurubashi, <sacerdote/sacerdotessa>. Persino i reali cominciano a parlare delle tue imprese. Si dice che re Rastakhan abbia perfino fatto il tuo nome.\n\nÈ giunto il momento di infondere l'Occhio. Dammi il talismano e compirò il rito.", "." },
  ["d4a0e6b176afa7dd"] = { "Ascolta, drago. Che la verità risuoni in tutte queste sale.", "." },
  ["d4a860f250e1f96c"] = { "Ho bisogno di addestramento, Nissa.", "." },
  ["d4add1a5aadc53bb"] = { "Finalmente il Soulflayer non mi tiene più!", "." },
  ["d4b3aa3a3cabc0a1"] = { "Tacerei sull'uccisione e lascerei che il cavaliere reclamasse la ricompensa per aiutare la sua famiglia.", "." },
  ["d4b567f7fae6799c"] = { "Ehi! Tu non dovresti stare qui! Forza, ragazzi!", "." },
  ["d4b7b42452ce0d48"] = { "C'è un odore strano.", "." },
  ["d4b94024132a9f2b"] = { "Non trovo affatto divertente la tua sfrontatezza nel venire da me per l'addestramento. Passa sotto l'arco e scendi la rampa verso sud-est, poi parla con il dottor Martin Felben. È un Reietto che può insegnarti le basi.", "." },
  ["d4beff6ab3752084"] = { "Guardami le spalle, qui potrebbe mettersi davvero male.", "." },
  ["d4c44b6d020b02a9"] = { "Voglio azzerare l'addestramento del mio famiglio.", "." },
  ["d4c5a3c23c28c047"] = { "Il capitano Redpath è stato ucciso!", "." },
  ["d4c69a0045d274bc"] = { "BRUCIA! IL DOLORE... STRAZIANTE...", "." },
  ["d4d00e5bdd99d209"] = { "Quando avrò gli orecchini, lancerò l'incantesimo per cercare dove si trova il sigillo che mi vincola. Per secoli ho pensato alla libertà che mi darebbe la distruzione del sigillo... Forse quei secoli hanno logorato la mia mente al punto che non potrò mai più riprendermi...", "." },
  ["d4d543a93bc58a09"] = { "Dolce Elune, grazie per avermi tirato fuori da quella... cosa!", "." },
  ["d4d6d5bd69a53d8b"] = { "A Caer Darrow non sono ammessi bighellonaggio, accattonaggio, imprecazioni, risse né qualunque altra cosa tu stia pensando di fare.", "." },
  ["d4d77240963518da"] = { "La stirpe di Onyxia!", "." },
  ["d4d774717e7be4c9"] = { "Me la pagherai!", "." },
  ["d4e3d3f078fa7a3f"] = { "Dov'è l'anziano Primestone?", "." },
  ["d4e48356dc5cc8e7"] = { "Allora è con Thelman Slatefist che vuoi parlare. Lo trovi al cospetto del re, nel Castello di ⟦Stormwind=Roccavento⟧.", "." },
  ["d4e550e46bef0ba5"] = { "E poi cosa fece Ragnaros?", "." },
  ["d4e86fc70fb73ea1"] = { "I Defias trionferanno! Nessun avventuriero smidollato ci fermerà!", "." },
  ["d4f508c301db50ad"] = { "Non ho altro da insegnarti. Parla con Karolek se vuoi migliorare le tue abilità di conciatura.", "." },
